with filtered as (select *, round(discount_pct, 0) as discount_pct_rounded, coalesce(channel, 'N/A') as resolved_channel from promotions where channel is not null and discount_pct <= 0.25) select id, starts_on, ends_on, discount_pct_rounded, resolved_channel, avg(discount_pct_rounded) over (order by starts_on, id rows between 5 preceding and current row) as discount_pct_rounded_avg_5, avg(discount_pct_rounded) over (partition by promo_code, channel order by ends_on, id rows between 3 preceding and current row) as discount_pct_rounded_avg_3, last_value(channel) ignore nulls over w_hist as last_known_channel from filtered window w_hist as (partition by promo_code order by ends_on, id rows between unbounded preceding and current row);
